-- PENDING: owner approval required; no rows, policies, ACLs or Role grants changed.
DO $$ BEGIN
 IF md5(pg_get_functiondef('private.org_role_rules(uuid,jsonb)'::regprocedure)) <> '3411ccfb43bf8f1519281a27690750ac' THEN RAISE EXCEPTION 'role rules baseline changed'; END IF;
 IF md5(pg_get_functiondef('private.org_slot_rules(uuid,jsonb)'::regprocedure)) <> 'a0724fa201571faeef6da5ec0a44a000' THEN RAISE EXCEPTION 'slot resolver baseline changed'; END IF;
 IF md5(pg_get_functiondef('private.slot_previous_source_rows(jsonb)'::regprocedure)) <> '54810e2df1dcf688f5024df0ce354dfa' THEN RAISE EXCEPTION 'source resolver baseline changed'; END IF;
 IF md5(pg_get_functiondef('private.org_commands(jsonb)'::regprocedure)) <> 'c759e726c6c627bbae8f113db9e0f285' THEN
 RAISE EXCEPTION 'org_commands baseline changed; re-audit required'; END IF;
END $$;
CREATE OR REPLACE FUNCTION private.org_commands(changes_ jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ DECLARE x jsonb;v jsonb;old_ record;title_ record;unit_ record;id_ text;parent_ text;at_ timestamptz;end_ timestamptz;category_ text;src_ text;scope_ text;d uuid;t uuid;s uuid;affected jsonb:='[]';before_ jsonb;after_ jsonb;expected_ jsonb;BEGIN
 IF jsonb_typeof(changes_) IS DISTINCT FROM 'array' OR jsonb_array_length(changes_) NOT BETWEEN 1 AND 500 THEN RAISE EXCEPTION 'Danh sách thay đổi không hợp lệ.';END IF;
 FOR x IN SELECT value FROM jsonb_array_elements(changes_) LOOP v:=x->'data';id_:=coalesce(nullif(v->>'id',''),gen_random_uuid()::text);
 IF x->>'action'='replace_slot_role' THEN
 IF NOT private.is_super_admin(auth.uid()) OR NOT private.org_execution_ok() THEN RAISE EXCEPTION 'Thay Role phải qua xem trước Super Admin.' USING ERRCODE='42501'; END IF;
 SELECT * INTO old_ FROM org_position_slots WHERE id=id_ AND active FOR UPDATE; IF old_.id IS NULL THEN RAISE EXCEPTION 'Ô không tồn tại hoặc đã ngừng.'; END IF;
 IF NOT EXISTS(SELECT 1 FROM app_roles WHERE id=v->>'role_id' AND role_kind='position' AND catalog_state='standard' AND NOT is_system) THEN RAISE EXCEPTION 'Role thay thế không hợp lệ.'; END IF;
 IF EXISTS(SELECT 1 FROM org_assignments WHERE slot_id=id_ AND status='active' AND starts_at>=now()) THEN RAISE EXCEPTION 'Ô có bổ nhiệm tương lai; cần đối chiếu riêng trước khi thay Role.'; END IF;
 expected_:=to_jsonb(old_); parent_:=gen_random_uuid()::text;
 affected:=affected||private.org_commands(jsonb_build_array(jsonb_build_object('action','slot','data',jsonb_build_object('id',parent_,'title_id',old_.title_id,'unit_id',old_.unit_id,'role_id',v->>'role_id','name',old_.name||' · phiên bản mới'))));
 FOR before_ IN SELECT to_jsonb(a) FROM org_assignments a WHERE slot_id=id_ AND status='active' AND starts_at<now() AND (ends_at IS NULL OR ends_at>now()) LOOP
 after_:=coalesce(before_->'data','{}')||jsonb_build_object('id',gen_random_uuid()::text,'unit_id',before_->>'unit_id','title_id',before_->>'title_id','user_id',before_->>'user_id','category',before_->>'category','kind',CASE WHEN before_->>'category'='concurrent' THEN 'concurrent' ELSE 'primary' END,'starts_at',now(),'ends_at',before_->'ends_at','slot_id',parent_,'immediate',true);
 affected:=affected||private.org_commands(jsonb_build_array(jsonb_build_object('action','end','data',jsonb_build_object('id',before_->>'id','ends_at',now(),'immediate',true)),jsonb_build_object('action','assign','data',after_)));
 END LOOP;
 UPDATE org_position_slots SET active=false,revision=revision+1 WHERE id=id_;
 affected:=affected||jsonb_build_array(expected_->>'unit_id');
 ELSIF x->>'action'='restore_slots' THEN
 IF NOT private.is_super_admin(auth.uid()) THEN RAISE EXCEPTION 'Chỉ Super Admin khôi phục chuyển ô.'; END IF;
 SELECT * INTO old_ FROM private.org_slot_snapshots WHERE id=id_::uuid FOR UPDATE;
 IF old_.id IS NULL OR old_.restored_at IS NOT NULL THEN RAISE EXCEPTION 'Snapshot không tồn tại hoặc đã khôi phục.'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(old_.after_data->'memberships') a JOIN org_assignments live ON live.id=a->>'id' WHERE a->>'slot_id' IS DISTINCT FROM (SELECT b->>'slot_id' FROM jsonb_array_elements(old_.before_data->'memberships') b WHERE b->>'id'=a->>'id') AND (live.status IS DISTINCT FROM a->>'status' OR live.slot_id IS DISTINCT FROM a->>'slot_id' OR live.starts_at IS DISTINCT FROM (a->>'starts_at')::timestamptz OR live.ends_at IS DISTINCT FROM nullif(a->>'ends_at','')::timestamptz)) THEN RAISE EXCEPTION 'Bổ nhiệm đã thay đổi; không ghi đè khi khôi phục.'; END IF;
 IF EXISTS(SELECT 1 FROM org_assignments live JOIN org_position_slots slot ON slot.id=live.slot_id WHERE EXISTS(SELECT 1 FROM jsonb_array_elements(old_.after_data->'position_slots') a WHERE a->>'id'=slot.id) AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(old_.before_data->'position_slots') b WHERE b->>'id'=slot.id) AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(old_.after_data->'memberships') original WHERE original->>'id'=live.id AND original->>'slot_id'=slot.id)) THEN RAISE EXCEPTION 'Ô đã có bổ nhiệm mới; không khôi phục đè dữ liệu.'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(old_.after_data->'position_slots') saved JOIN org_position_slots live ON live.id=saved->>'id' WHERE live.role_id IS DISTINCT FROM saved->>'role_id' OR live.title_id IS DISTINCT FROM saved->>'title_id' OR live.unit_id IS DISTINCT FROM saved->>'unit_id' OR live.name IS DISTINCT FROM saved->>'name' OR live.active IS DISTINCT FROM (saved->>'active')::boolean) THEN RAISE EXCEPTION 'Ô vị trí đã thay đổi; không khôi phục ghi đè.'; END IF;
 UPDATE org_assignments live SET slot_id=NULL,data=data-'slot_id',revision=revision+1 WHERE EXISTS(SELECT 1 FROM jsonb_array_elements(old_.after_data->'memberships') a WHERE a->>'id'=live.id AND a->>'slot_id'=live.slot_id) AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(old_.before_data->'memberships') b WHERE b->>'id'=live.id AND nullif(b->>'slot_id','') IS NOT NULL);
 UPDATE org_position_slots slot SET active=false,revision=revision+1 WHERE EXISTS(SELECT 1 FROM jsonb_array_elements(old_.after_data->'position_slots') a WHERE a->>'id'=slot.id) AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(old_.before_data->'position_slots','[]')) b WHERE b->>'id'=slot.id);
 UPDATE private.org_slot_snapshots SET restored_at=now() WHERE id=old_.id;
 affected:=affected||jsonb_build_array('org-company');
 ELSIF x->>'action'='slot' THEN
 IF NOT private.is_super_admin(auth.uid()) THEN RAISE EXCEPTION 'Chỉ Super Admin tạo ô vị trí.'; END IF;
 PERFORM private.org_require('org.manage_structure',v->>'unit_id');
 IF NOT EXISTS(SELECT 1 FROM org_titles WHERE id=v->>'title_id' AND active AND (unit_id IS NULL OR unit_id=v->>'unit_id')) OR coalesce(trim(v->>'name'),'')='' THEN RAISE EXCEPTION 'Chức danh/đơn vị ô vị trí không hợp lệ.'; END IF;
 INSERT INTO org_position_slots(id,title_id,unit_id,role_id,name,active,created_by) VALUES(id_,v->>'title_id',v->>'unit_id',v->>'role_id',trim(v->>'name'),coalesce((v->>'active')::boolean,true),auth.uid()) ON CONFLICT(id) DO UPDATE SET name=excluded.name,active=excluded.active,revision=org_position_slots.revision+1;
 affected:=affected||jsonb_build_array(v->>'unit_id');
 ELSIF x->>'action'='bind_slot' THEN
 IF NOT private.is_super_admin(auth.uid()) THEN RAISE EXCEPTION 'Chỉ Super Admin chuyển ô vị trí.'; END IF;
 SELECT * INTO old_ FROM org_assignments WHERE id=id_ FOR UPDATE;
 IF old_.id IS NULL OR old_.slot_id IS NOT NULL THEN RAISE EXCEPTION 'Phân công đã chuyển hoặc không tồn tại.'; END IF;
 PERFORM private.org_require('org.manage_structure',old_.unit_id);
 IF NOT EXISTS(SELECT 1 FROM org_position_slots s WHERE s.id=v->>'slot_id' AND s.unit_id=old_.unit_id AND s.title_id=old_.title_id AND s.role_id=v->>'reviewed_role') THEN RAISE EXCEPTION 'Mapping phải xem trước đúng Role, chức danh và đơn vị.'; END IF;
 UPDATE org_assignments SET slot_id=v->>'slot_id',data=jsonb_set(data,'{slot_id}',to_jsonb(v->>'slot_id')),revision=revision+1 WHERE id=id_;
 affected:=affected||jsonb_build_array(old_.unit_id);
 ELSIF x->>'action'='unit' THEN SELECT * INTO old_ FROM org_units WHERE id=id_;parent_:=nullif(v->>'parent_id',''); IF parent_ IS NOT NULL THEN PERFORM private.org_require('org.manage_structure',parent_);END IF; IF old_.id IS NOT NULL THEN PERFORM private.org_require('org.manage_structure',old_.id);IF old_.kind<>v->>'kind' THEN RAISE EXCEPTION 'Không đổi loại đơn vị đã tồn tại.';END IF; ELSIF parent_ IS NULL AND NOT private.is_super_admin(auth.uid()) THEN RAISE EXCEPTION 'Chỉ Super Admin tạo đơn vị gốc.';END IF;
 IF coalesce(trim(v->>'name'),'')='' OR v->>'kind' NOT IN ('company','block','system','department','team') THEN RAISE EXCEPTION 'Đơn vị không hợp lệ.';END IF; IF parent_=id_ OR private.org_contains(id_,parent_) THEN RAISE EXCEPTION 'Cơ cấu bị vòng lặp.';END IF;
 IF parent_ IS NOT NULL AND NOT EXISTS(SELECT 1 FROM org_units WHERE id=parent_ AND active) THEN RAISE EXCEPTION 'Đơn vị cha đã ngừng hoặc không tồn tại.';END IF;
 IF NOT coalesce((v->>'active')::boolean,true) AND (EXISTS(SELECT 1 FROM org_units WHERE parent_id=id_ AND active) OR EXISTS(SELECT 1 FROM org_assignments WHERE unit_id=id_ AND status<>'cancelled' AND (ends_at IS NULL OR ends_at>clock_timestamp()))) THEN RAISE EXCEPTION 'Đơn vị còn đơn vị con hoặc phân công hiệu lực/tương lai.';END IF;
 src_:=coalesce(old_.source,CASE WHEN private.org_contains('biz-block',parent_) THEN CASE v->>'kind' WHEN 'system' THEN 'biz_systems' WHEN 'department' THEN 'biz_departments' WHEN 'team' THEN 'biz_teams' ELSE 'canonical' END ELSE 'canonical' END);
 IF old_.id IS NOT NULL AND old_.parent_id IS DISTINCT FROM parent_ THEN INSERT INTO org_parent_history(id,unit_id,parent_id,starts_at,source,data) VALUES(gen_random_uuid()::text,id_,old_.parent_id,clock_timestamp(),'canonical',to_jsonb(old_));END IF;
 INSERT INTO org_units(id,parent_id,kind,name,active,source,source_id,data) VALUES(id_,parent_,v->>'kind',trim(v->>'name'),coalesce((v->>'active')::boolean,true),src_,id_,v) ON CONFLICT(id) DO UPDATE SET parent_id=excluded.parent_id,name=excluded.name,active=excluded.active,data=excluded.data,revision=org_units.revision+1;
 IF src_='biz_systems' THEN IF old_.id IS NOT NULL AND parent_ IS DISTINCT FROM old_.parent_id THEN RAISE EXCEPTION 'Hệ Kinh doanh giữ liên kết nghiệp vụ với Khối Kinh doanh.';END IF;INSERT INTO biz_systems(id,name,active) VALUES(id_::uuid,v->>'name',coalesce((v->>'active')::boolean,true)) ON CONFLICT(id) DO UPDATE SET name=excluded.name,active=excluded.active;
 ELSIF src_='biz_departments' THEN IF parent_ IS NOT NULL AND NOT EXISTS(SELECT 1 FROM biz_systems WHERE id=parent_::uuid AND active) THEN RAISE EXCEPTION 'Phòng Kinh doanh cần Hệ nghiệp vụ hợp lệ.';END IF; IF old_.id IS NOT NULL AND old_.parent_id IS DISTINCT FROM parent_ AND EXISTS(SELECT 1 FROM biz_appointments WHERE department_id=id_::uuid AND status<>'cancelled' AND (ended_at IS NULL OR ended_at>clock_timestamp())) THEN RAISE EXCEPTION 'Phòng còn bổ nhiệm: cần đối chiếu phạm vi trước khi đổi Hệ.';END IF;INSERT INTO biz_departments(id,name,active,system_id) VALUES(id_::uuid,v->>'name',coalesce((v->>'active')::boolean,true),parent_::uuid) ON CONFLICT(id) DO UPDATE SET name=excluded.name,active=excluded.active,system_id=excluded.system_id; IF parent_ IS NOT NULL AND (old_.id IS NULL OR old_.parent_id IS DISTINCT FROM parent_) THEN UPDATE biz_department_system_history SET ended_at=clock_timestamp() WHERE department_id=id_::uuid AND ended_at IS NULL;INSERT INTO biz_department_system_history(department_id,system_id,actor_id) VALUES(id_::uuid,parent_::uuid,auth.uid());END IF;
 ELSIF src_='biz_teams' THEN IF old_.id IS NOT NULL AND old_.parent_id IS DISTINCT FROM parent_ THEN RAISE EXCEPTION 'Nhóm đã có định danh nghiệp vụ; không đổi Phòng khi chưa đối chiếu phụ thuộc.';END IF;INSERT INTO biz_teams(id,department_id,name,active) VALUES(id_::uuid,parent_::uuid,v->>'name',coalesce((v->>'active')::boolean,true)) ON CONFLICT(id) DO UPDATE SET name=excluded.name,active=excluded.active;END IF;affected:=affected||jsonb_build_array(id_);
 ELSIF x->>'action'='title' THEN SELECT * INTO old_ FROM org_titles WHERE id=id_;scope_:=coalesce(nullif(v->>'unit_id',''),'org-company');PERFORM private.org_require('org.manage_structure',scope_);IF old_.unit_id IS NOT NULL THEN PERFORM private.org_require('org.manage_structure',old_.unit_id);END IF;
 IF coalesce(trim(v->>'name'),'')='' OR v->>'kind' NOT IN ('manager','staff') OR (v->>'level')::int NOT BETWEEN 0 AND 5 OR (v->>'capacity')::int<0 THEN RAISE EXCEPTION 'Chức vụ/cấp bậc không hợp lệ.';END IF;
 src_:=coalesce(old_.source,CASE WHEN coalesce(v->>'business_policy','none')<>'none' THEN 'biz_positions' ELSE 'canonical' END);
 IF src_='biz_positions' THEN IF NOT private.is_super_admin(auth.uid()) THEN RAISE EXCEPTION 'Chức vụ nghiệp vụ cần Super Admin xác nhận phạm vi.';END IF;INSERT INTO biz_positions(id,code,name,description,level,unit_kind,active,business_policy,all_business) VALUES(id_::uuid,v->>'code',v->>'name',coalesce(v->>'description',''),(v->>'level')::int,v->>'unit_kind',coalesce((v->>'active')::boolean,true),v->>'business_policy',coalesce((v->>'all_business')::boolean,false)) ON CONFLICT(id) DO UPDATE SET name=excluded.name,description=excluded.description,level=excluded.level,unit_kind=excluded.unit_kind,active=excluded.active,business_policy=excluded.business_policy,all_business=excluded.all_business,code=excluded.code;END IF;
 INSERT INTO org_titles(id,unit_id,name,code,level,kind,capacity,active,source,source_id,data) VALUES(id_,nullif(v->>'unit_id',''),v->>'name',v->>'code',(v->>'level')::int,v->>'kind',(v->>'capacity')::int,coalesce((v->>'active')::boolean,true),src_,id_,v) ON CONFLICT(id) DO UPDATE SET unit_id=excluded.unit_id,name=excluded.name,code=excluded.code,level=excluded.level,kind=excluded.kind,capacity=excluded.capacity,active=excluded.active,data=excluded.data,revision=org_titles.revision+1;affected:=affected||jsonb_build_array(scope_);
 ELSIF x->>'action'='assign' THEN SELECT * INTO unit_ FROM org_units WHERE id=v->>'unit_id'; SELECT * INTO title_ FROM org_titles WHERE id=v->>'title_id';IF unit_.id IS NULL OR title_.id IS NULL OR NOT unit_.active OR NOT title_.active THEN RAISE EXCEPTION 'Đơn vị/chức vụ đã ngừng hoặc không tồn tại.';END IF;PERFORM private.org_require('org.assign_staff',unit_.id);IF title_.kind='manager' OR title_.capacity=1 THEN PERFORM private.org_require('org.appoint_manager',unit_.id);IF v->>'user_id'=auth.uid()::text AND NOT private.is_super_admin(auth.uid()) THEN RAISE EXCEPTION 'Không thể tự bổ nhiệm mình vào vị trí quản lý.';END IF;END IF;
 IF title_.unit_id IS NOT NULL AND title_.unit_id<>unit_.id THEN RAISE EXCEPTION 'Chức vụ không thuộc đơn vị này.';END IF;IF NOT EXISTS(SELECT 1 FROM profiles WHERE id=(v->>'user_id')::uuid AND status='Đang hoạt động') THEN RAISE EXCEPTION 'Nhân viên chưa hoạt động.';END IF;
 IF title_.source IS DISTINCT FROM 'biz_positions' AND v->>'user_id'=auth.uid()::text AND NOT private.is_super_admin(auth.uid()) AND EXISTS(SELECT 1 FROM base_title_role_links l WHERE l.title_source='base' AND l.title_id=title_.id AND cardinality(l.enabled_permissions)>0) THEN RAISE EXCEPTION 'Không tự phân công vào chức vụ có quyền tự cấp; cần quản trị khác xác nhận.';END IF;
 IF coalesce(v->'specialty_ids','[]')<>'[]'::jsonb THEN
 IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(v->'specialty_ids') sid JOIN mkt_specialties sp ON sp.id=sid JOIN app_roles r ON r.id=sp.role_id WHERE r.role_kind='marketing_task') AND NOT EXISTS(SELECT 1 FROM org_units b WHERE b.kind='block' AND b.name='Khối Marketing' AND private.base_role_unit_contains(private.org_config(),b.id,unit_.id)) THEN RAISE EXCEPTION 'Nhiệm vụ Marketing chỉ gắn với bổ nhiệm trong Khối Marketing.'; END IF;
 
 IF title_.source='biz_positions' OR NOT private.is_super_admin(auth.uid()) THEN RAISE EXCEPTION 'Nhiệm vụ theo phân công chỉ cho Super Admin, không thay đổi Kinh doanh.';END IF;
 IF jsonb_typeof(v->'specialty_ids') IS DISTINCT FROM 'array' OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(v->'specialty_ids') picked(specialty_id) WHERE NOT EXISTS(SELECT 1 FROM mkt_specialties s WHERE s.id=picked.specialty_id AND s.active AND s.role_id NOT IN ('role-admin','role-super-admin'))) THEN RAISE EXCEPTION 'Nhiệm vụ Marketing không hợp lệ.';END IF;
 v:=v||jsonb_build_object('specialty_signatures',(SELECT jsonb_object_agg(s.id,md5(coalesce(r.permissions,'{}')::text)) FROM mkt_specialties s JOIN app_roles r ON r.id=s.role_id WHERE s.id IN (SELECT jsonb_array_elements_text(v->'specialty_ids'))));
 ELSE v:=v-'specialty_signatures';END IF;
 at_:=coalesce(nullif(v->>'starts_at','')::timestamptz,clock_timestamp());end_:=nullif(v->>'ends_at','')::timestamptz;IF at_<clock_timestamp()-interval '10 minutes' OR end_<=at_ THEN RAISE EXCEPTION 'Không tạo phân công hồi tố hoặc thời hạn không hợp lệ.';END IF;category_:=coalesce(v->>'kind','primary');IF category_ NOT IN ('primary','concurrent') THEN RAISE EXCEPTION 'Chọn phân công chính hoặc kiêm nhiệm.';END IF;
 IF nullif(v->>'slot_id','') IS NOT NULL THEN RAISE EXCEPTION 'Ô cũ chỉ dùng lịch sử; bổ nhiệm theo đơn vị và chức danh.' USING ERRCODE='42501'; END IF;
 PERFORM pg_advisory_xact_lock(hashtext('org-position:'||unit_.id||':'||title_.id));
 IF EXISTS(SELECT 1 FROM org_assignments WHERE unit_id=unit_.id AND title_id=title_.id AND status<>'cancelled' AND tstzrange(starts_at,ends_at,'[)')&&tstzrange(at_,end_,'[)') AND user_id=(v->>'user_id')::uuid AND (nullif(v->>'slot_id','') IS NULL OR slot_id=v->>'slot_id')) THEN RAISE EXCEPTION 'Trùng phân công trong khoảng hiệu lực.';END IF;
 IF nullif(v->>'slot_id','') IS NULL AND title_.kind='manager' AND title_.capacity>0 AND (SELECT count(*) FROM org_assignments WHERE unit_id=unit_.id AND title_id=title_.id AND status<>'cancelled' AND tstzrange(starts_at,ends_at,'[)')&&tstzrange(at_,end_,'[)'))>=title_.capacity THEN RAISE EXCEPTION 'Vị trí vượt số người tối đa trong khoảng hiệu lực.';END IF;
 IF category_='primary' AND EXISTS(SELECT 1 FROM org_assignments WHERE user_id=(v->>'user_id')::uuid AND category='primary' AND unit_id<>unit_.id AND status<>'cancelled' AND tstzrange(starts_at,ends_at,'[)')&&tstzrange(at_,end_,'[)')) THEN RAISE EXCEPTION 'Chọn phân công nguồn cần kết thúc trước khi điều chuyển.';END IF;
 IF title_.source='biz_positions' THEN s:=NULL;d:=NULL;t:=NULL;IF unit_.kind='system' THEN s:=unit_.id::uuid;ELSIF unit_.kind='department' THEN d:=unit_.id::uuid;ELSIF unit_.kind='team' THEN t:=unit_.id::uuid;ELSIF unit_.kind<>'company' THEN RAISE EXCEPTION 'Chức vụ nghiệp vụ cần đơn vị tương thích.';END IF;PERFORM private.org_biz_appointment(jsonb_build_object('position_id',title_.id,'user_id',v->>'user_id','system_id',s,'department_id',d,'team_id',t,'started_at',at_,'ended_at',end_),id_::uuid);src_:='biz_appointments';category_:='appointment';ELSE src_:='canonical';END IF;
 IF nullif(v->>'slot_id','') IS NULL AND NOT EXISTS(
 SELECT 1 FROM org_position_roles pr JOIN app_roles r ON r.id=pr.role_id
 WHERE pr.unit_id=unit_.id AND pr.title_id=title_.id AND r.role_kind='position'
 AND r.catalog_state='standard' AND r.catalog_generation>=2 AND NOT r.is_system
 AND r.id NOT IN ('role-admin','role-super-admin')
 ) THEN RAISE EXCEPTION 'Vị trí chưa gắn Role V2 hợp lệ; cần quản trị kiểm tra mapping.' USING ERRCODE='42501'; END IF;
 INSERT INTO org_assignments(id,unit_id,title_id,user_id,category,starts_at,ends_at,source,source_id,data,slot_id) VALUES(id_,unit_.id,title_.id,(v->>'user_id')::uuid,category_,at_,end_,src_,id_,v,nullif(v->>'slot_id',''));affected:=affected||jsonb_build_array(unit_.id);
 ELSIF x->>'action' IN ('end','cancel') THEN SELECT * INTO old_ FROM org_assignments WHERE id=id_ FOR UPDATE;IF old_.id IS NULL THEN RAISE EXCEPTION 'Không tìm thấy phân công nguồn.';END IF;PERFORM private.org_require('org.assign_staff',old_.unit_id);SELECT * INTO title_ FROM org_titles WHERE id=old_.title_id;IF old_.category='legacy_manager' OR title_.kind='manager' THEN PERFORM private.org_require('org.appoint_manager',old_.unit_id);END IF;
 IF old_.status='cancelled' OR old_.ends_at<=clock_timestamp() THEN RAISE EXCEPTION 'Không sửa phân công đã kết thúc.';END IF;at_:=coalesce(nullif(v->>'ends_at','')::timestamptz,clock_timestamp());IF x->>'action'='cancel' THEN IF old_.starts_at<=clock_timestamp() THEN RAISE EXCEPTION 'Chỉ hủy phân công chưa hiệu lực.';END IF; ELSE IF at_<=old_.starts_at OR at_<clock_timestamp()-interval '10 minutes' THEN RAISE EXCEPTION 'Mốc kết thúc không hợp lệ.';END IF;
 IF old_.source NOT LIKE 'biz_%' AND old_.ends_at IS NOT NULL AND at_>old_.ends_at THEN RAISE EXCEPTION 'Không gia hạn phân công bằng thao tác kết thúc.';END IF;END IF;
 IF old_.source='biz_appointments' THEN UPDATE biz_appointments SET ended_at=CASE WHEN x->>'action'='cancel' THEN ended_at ELSE at_ END,status=CASE WHEN x->>'action'='cancel' THEN 'cancelled' ELSE 'active' END WHERE id=old_.source_id::uuid; UPDATE biz_member_affiliations SET ended_at=CASE WHEN x->>'action'='cancel' THEN started_at+interval '1 microsecond' ELSE at_ END WHERE appointment_id=old_.source_id::uuid AND (ended_at IS NULL OR ended_at>at_);
 ELSIF old_.source='biz_department_members' THEN IF x->>'action'='cancel' THEN RAISE EXCEPTION 'Phân công Phòng cũ chưa có trạng thái hủy; cần đối chiếu riêng.';END IF;UPDATE biz_department_members SET ended_at=at_,effective_to=(at_ AT TIME ZONE 'Asia/Ho_Chi_Minh')::date WHERE id=old_.source_id::uuid;
 ELSIF old_.source='biz_team_members' THEN UPDATE biz_team_members SET ended_at=at_ WHERE id=old_.source_id::uuid;
 ELSIF old_.source='biz_member_affiliations' THEN UPDATE biz_member_affiliations SET ended_at=at_ WHERE id=old_.source_id::uuid;
 ELSIF old_.source='biz_management_assignments' THEN UPDATE biz_management_assignments SET ended_at=at_ WHERE id=old_.source_id::uuid;END IF;
 UPDATE org_assignments SET ends_at=CASE WHEN x->>'action'='cancel' THEN ends_at ELSE at_ END,status=CASE WHEN x->>'action'='cancel' THEN 'cancelled' ELSE 'active' END,revision=revision+1 WHERE id=id_;affected:=affected||jsonb_build_array(old_.unit_id);
 ELSIF x->>'action'='roles' THEN IF NOT private.is_super_admin(auth.uid()) THEN RAISE EXCEPTION 'Chỉ Super Admin được chỉnh Role mặc định.';END IF;IF NOT EXISTS(SELECT 1 FROM org_titles WHERE id=id_) THEN RAISE EXCEPTION 'Chức vụ không tồn tại.';END IF;IF EXISTS(SELECT 1 FROM jsonb_array_elements(v->'roles') r WHERE coalesce((r->>'active')::boolean,false) OR r->>'role_id' IN ('role-admin','role-super-admin') OR NOT EXISTS(SELECT 1 FROM app_roles WHERE id=r->>'role_id')) THEN RAISE EXCEPTION 'Role chưa thể kích hoạt hoặc không hợp lệ.';END IF;SELECT source INTO src_ FROM org_titles WHERE id=id_;src_:=CASE WHEN src_='biz_positions' THEN 'biz' ELSE 'base' END;
 SELECT coalesce(jsonb_agg(to_jsonb(l) ORDER BY role_id),'[]') INTO before_ FROM base_title_role_links l WHERE title_source=src_ AND title_id=id_; DELETE FROM base_title_role_links WHERE title_source=src_ AND title_id=id_;INSERT INTO base_title_role_links(title_source,title_id,role_id,is_primary,scope_kind,active,reason,updated_by) SELECT src_,id_,r->>'role_id',coalesce((r->>'is_primary')::boolean,false),coalesce(r->>'scope_kind','unit'),false,coalesce(v->>'reason','Cơ cấu tổ chức'),auth.uid() FROM jsonb_array_elements(v->'roles') r;SELECT coalesce(jsonb_agg(to_jsonb(l) ORDER BY role_id),'[]') INTO after_ FROM base_title_role_links l WHERE title_source=src_ AND title_id=id_;INSERT INTO base_title_role_events(actor_id,title_source,title_id,reason,before_data,after_data) VALUES(auth.uid(),src_,id_,coalesce(v->>'reason','Cơ cấu tổ chức'),before_,after_);affected:=affected||jsonb_build_array('org-company');
 ELSE RAISE EXCEPTION 'Thao tác chưa được hỗ trợ an toàn: %',x->>'action';END IF;
 END LOOP; RETURN affected;END $function$
;

-- Historical slot_id remains provenance only. No assignment row is rewritten.
CREATE OR REPLACE FUNCTION private.org_slot_rules(u uuid,c jsonb) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public' AS $function$
 SELECT coalesce(jsonb_agg(x.rule),'[]'::jsonb) FROM (
 SELECT jsonb_build_object('id',(m->>'id')||':'||r.id||':'||p,'permission',p,'effect','ALLOW','scope','native','active',true,'source_kind','appointment_role','source_id',m->>'id','source_name',r.name,'role_id',r.id,'unit_id',m->>'unit_id','slot_id',NULL,'starts_at',m->>'starts_at','ends_at',m->>'ends_at','legacy',false) rule
 FROM jsonb_array_elements(coalesce(c->'memberships','[]')) m JOIN public.org_position_roles b ON b.unit_id=m->>'unit_id' AND b.title_id=m->>'title_id' JOIN LATERAL jsonb_array_elements(coalesce(c->'titles','[]')) t ON t->>'id'=m->>'title_id' JOIN app_roles r ON r.id=b.role_id AND r.role_kind='position' AND r.catalog_state='standard' AND NOT r.is_system AND r.catalog_generation>=2 CROSS JOIN LATERAL unnest(r.permissions) p
 WHERE private.is_active(u) AND m->>'user_id'=u::text AND private.base_valid_at(m) AND coalesce(m->>'status','active')='active' AND coalesce((t->>'active')::boolean,false) AND private.org_role_permission_ready(p)
) x $function$
;

-- Provenance reads now agree with canonical source; specialties/direct sources unchanged.
CREATE OR REPLACE FUNCTION private.slot_previous_source_rows(c jsonb)
 RETURNS TABLE(user_id uuid, role_id text, source_kind text, source_id text, unit_id text, legacy boolean, eligible boolean, scope text, permissions text[])
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
 SELECT (m->>'user_id')::uuid,r.id,'position',m->>'id',m->>'unit_id',false,true,'native',ARRAY(SELECT p FROM unnest(r.permissions) p WHERE private.org_role_permission_ready(p))
 FROM jsonb_array_elements(coalesce(c->'memberships','[]')) m
 JOIN org_position_roles b ON b.unit_id=m->>'unit_id' AND b.title_id=m->>'title_id'
 JOIN LATERAL jsonb_array_elements(coalesce(c->'titles','[]')) t ON t->>'id'=m->>'title_id'
 JOIN app_roles r ON r.id=b.role_id AND r.role_kind='position' AND r.catalog_state='standard' AND r.catalog_generation>=2 AND NOT r.is_system
 WHERE private.base_valid_at(m) AND coalesce(m->>'status','active')='active' AND coalesce((t->>'active')::boolean,false) AND private.is_active((m->>'user_id')::uuid)
 UNION ALL SELECT m.user_id,r.id,CASE WHEN r.role_kind='marketing_task' THEN 'task' ELSE 'specialty' END,m.specialty_id,NULL,NOT m.eligibility_enforced,r.role_kind<>'marketing_task' OR private.org_marketing_eligible(m.user_id,c),'own',ARRAY(SELECT p FROM unnest(r.permissions) p WHERE private.mkt_specialty_permission_ready(p)) FROM mkt_staff_specialties m JOIN mkt_specialties s ON s.id=m.specialty_id AND s.active JOIN app_roles r ON r.id=s.role_id WHERE m.state='active' AND private.is_active(m.user_id) AND (r.role_kind<>'marketing_task' OR NOT m.eligibility_enforced OR private.org_marketing_eligible(m.user_id,c)) UNION ALL SELECT ur.user_id,r.id,'direct',r.id,NULL,true,true,'native',r.permissions FROM user_roles ur JOIN app_roles r ON r.id=ur.role_id WHERE private.is_active(ur.user_id) $function$;

-- Retire legacy title fallback; inactive links must never revive on slotless appointments.
CREATE OR REPLACE FUNCTION private.org_role_rules(u uuid,c jsonb) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO public AS $$ SELECT private.org_slot_rules(u,c) $$;
COMMENT ON COLUMN public.org_assignments.slot_id IS 'DEPRECATED for authorization and new appointments: retained only as historical provenance; live position Role comes from org_position_roles(unit_id,title_id).';